# ruff: noqa: E501  # Embedded HTML/CSS/JavaScript is intentionally kept as one asset.
"""Static browser interface for the project-models-only ANPR V1 runtime."""

HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ANPR V1 Project Models Review</title><style>
:root{--ink:#172033;--muted:#667085;--blue:#2457d6;--green:#087443;--red:#b42318;--amber:#8a5200;--line:#dce2ea;--bg:#f4f6f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px Inter,system-ui,sans-serif}header{background:#101828;color:white;padding:20px 28px;display:flex;justify-content:space-between;gap:20px;align-items:center}h1{margin:0;font-size:22px}.sub{color:#bac5d6;margin-top:5px}.health{background:#20304b;padding:10px 14px;border-radius:10px}.wrap{max-width:1800px;margin:auto;padding:24px}.panel{background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px #1018280d}.drop{border:2px dashed #8ea9e8;border-radius:12px;padding:26px;text-align:center;background:#f8faff}.btn,button{border:0;border-radius:8px;padding:10px 15px;background:var(--blue);color:white;font-weight:700;cursor:pointer}button.secondary{background:#e8edf6;color:#23324b}.progress{height:8px;background:#e8edf3;border-radius:8px;overflow:hidden;margin:12px 0}.progress>div{height:100%;background:var(--blue)}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:8px}.metric{background:#f7f9fc;border-radius:8px;padding:10px}.metric b{font-size:19px;display:block}.views{display:flex;gap:8px;margin-bottom:12px}.guided{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.media{background:#101722;border-radius:10px;min-height:220px;display:flex;align-items:center;justify-content:center}.media img{width:100%;height:300px;object-fit:contain}.decision{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:16px;border:2px solid var(--line);padding:16px;border-radius:10px}.model,.resolved{padding:15px;border-radius:9px}.model{background:#eef4ff}.resolved{background:#f0faf5}.eyebrow{font-size:12px;font-weight:900;letter-spacing:.12em}.prediction{font:800 30px ui-monospace,monospace;letter-spacing:2px}.badge{display:inline-block;padding:9px 12px;border-radius:9px;font-weight:900;margin:8px 0;background:#fff0cc;color:var(--amber)}.badge.confirmed{background:#d9f5e5;color:var(--green)}.badge.corrected{background:#e6edff;color:#193b91}.badge.failure{background:#ffe2e2;color:var(--red)}.note{color:var(--muted);font-size:12px}.controls{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:16px}.choice{display:flex;gap:8px;flex-wrap:wrap}.choice label{border:1px solid var(--line);padding:9px;border-radius:8px;cursor:pointer}.choice label:has(input:checked){outline:2px solid var(--blue)}input,select,textarea{font:inherit}textarea,.text{width:100%;padding:9px;border:1px solid var(--line);border-radius:7px}.nav{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}table{width:100%;border-collapse:collapse;min-width:1100px}th,td{border-bottom:1px solid var(--line);padding:10px;text-align:left;vertical-align:top}th{position:sticky;top:0;background:#f8fafc}.tablewrap{overflow:auto}td img{width:230px;height:150px;object-fit:contain;background:#eef1f5}.hidden{display:none!important}.error{color:var(--red)}@media(max-width:1100px){.guided,.decision,.controls{grid-template-columns:1fr 1fr}}@media(max-width:700px){.guided,.decision,.controls{grid-template-columns:1fr}.media img{height:280px}}
</style></head><body><header><div><h1>ANPR V1 — Project Models Only</h1><div class="sub">Project Detection → project crop refinement → project Official Recognition → owner review</div></div><div class="health" id="health">Loading health…</div></header><main class="wrap">
<section class="panel" id="uploadPanel"><h2>Start or resume a batch</h2><div class="drop"><input id="files" type="file" multiple accept=".jpg,.jpeg,.png,image/jpeg,image/png"><p>Choose JPG/JPEG/PNG vehicle images</p><small>All inference is local. Every Recognition prediction requires owner review.</small></div><p><button id="start">Start Review</button> <select id="resume"><option value="">Resume a batch…</option></select></p><div id="uploadError" class="error"></div></section>
<section class="panel hidden" id="workspace"><div><b id="batchId"></b> · <span id="progressText"></span></div><div class="progress"><div id="bar"></div></div><div id="summary" class="summary"></div><div class="views"><button id="guidedBtn">Guided Review</button><button class="secondary" id="tableBtn">Batch Table</button><a class="btn" id="jsonExport">JSON</a><a class="btn" id="jsonlExport">JSONL</a><a class="btn" id="csvExport">CSV</a></div>
<div id="guided"><div class="guided"><div><h3>Raw Image</h3><div class="media"><img id="raw"></div></div><div><h3>Detection-Annotated Image</h3><div class="media"><img id="annotated"></div></div><div><h3>Detection Crop</h3><div class="media"><img id="detectedCrop"></div></div><div><h3>Refined Recognition Crop</h3><div class="media"><img id="crop"></div></div><div class="decision"><div class="model"><div class="eyebrow">MODEL PREDICTION</div><div class="prediction" id="modelPrediction">—</div><div id="confidence">Confidence: — · INFORMATIONAL ONLY</div><div id="structural">Turkish structural validation: —</div><div class="note">Structural validity describes syntax only; it does not prove that the characters are correct.</div></div><div class="resolved"><div class="eyebrow">RESOLVED RESULT</div><div class="prediction" id="resolvedText">—</div><div class="badge" id="statusBadge">MODEL PREDICTION — OWNER REVIEW REQUIRED</div><div id="resolutionSource">Resolution source: UNRESOLVED</div></div><div id="errors" class="error"></div></div>
<div class="controls"><fieldset><legend><b>Detection review</b></legend><b>Detection correct?</b><div class="choice" id="detChoices"></div><select id="reason"><option value="">Detection reason (optional)</option><option>NO_PLATE_DETECTED</option><option>WRONG_OBJECT</option><option>WRONG_TOP1</option><option>BOX_TOO_TIGHT</option><option>BOX_TOO_LOOSE</option><option>PARTIAL_PLATE</option><option>MULTIPLE_CANDIDATES</option><option>OTHER</option></select></fieldset><fieldset><legend><b>Recognition owner resolution</b></legend><b>Project model prediction correct?</b><div class="choice" id="recognitionChoices"></div><input class="text" id="corrected" placeholder="Corrected plate text (required when incorrect)"><textarea id="comment" placeholder="Owner comment"></textarea><small>CORRECT confirms the project model. INCORRECT requires a correction. Until then, the resolved result remains null.</small></fieldset></div></div><div class="nav"><button class="secondary" id="previous">Previous</button><button class="secondary" id="save">Save</button><button id="saveContinue">Save & Continue</button><button class="secondary" id="next">Next</button></div></div>
<div id="tableView" class="hidden"><div class="tablewrap"><table><thead><tr><th>Raw Image</th><th>Detection</th><th>Project Model Prediction</th><th>Resolved Result</th><th>Owner Assessments</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></div></section></main>
<script>
let batch=null,index=0;const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opt){let r=await fetch(url,opt),j=await r.json();if(!r.ok)throw Error(j.error?.message||r.statusText);return j}
async function init(){let h=await api('/api/health');$('health').innerHTML=`<b>${esc(h.status)} · ${esc(h.device.toUpperCase())}</b><br>${esc(h.detector.name)} / ${esc(h.recognizer.name)} · project models only`;let x=await api('/api/batches');x.batches.forEach(b=>$('resume').insertAdjacentHTML('beforeend',`<option>${esc(b.batch_id)}</option>`))}
async function start(){try{let f=new FormData();[...$('files').files].forEach(x=>f.append('images',x));batch=await api('/api/batches',{method:'POST',body:f});await processQueue()}catch(e){$('uploadError').textContent=e.message}}
async function processQueue(){show();while(batch.records.some(r=>r.state==='PENDING')){let x=await api(`/api/batches/${batch.batch_id}/infer-next`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});batch=x.batch;render()}render()}
function show(){$('workspace').classList.remove('hidden');$('batchId').textContent=batch.batch_id;['json','jsonl','csv'].forEach(k=>$(k+'Export').href=`/api/batches/${batch.batch_id}/export?format=${k}`)}
function selected(name){return document.querySelector(`input[name=${name}]:checked`)?.value||'UNREVIEWED'}
function choices(root,name,states,value){root.innerHTML=states.map(s=>`<label><input type="radio" name="${name}" value="${s}" ${s===value?'checked':''}> ${s}</label>`).join('')}
function record(){return batch.records[index]}
function resolution(z,review){let raw=z.recognition?.raw_text;if(review.official_raw_assessment==='CORRECT'&&raw)return {status:'OWNER CONFIRMED',text:raw,source:'OWNER_CONFIRMED_PROJECT_MODEL'};if(review.official_raw_assessment==='INCORRECT'&&review.corrected_plate_text)return {status:'OWNER CORRECTED',text:review.corrected_plate_text,source:'OWNER_CORRECTED'};let d=z.project_release_decision||{};return {status:d.primary_status||'MODEL PREDICTION — OWNER REVIEW REQUIRED',text:null,source:'UNRESOLVED'}}
function render(){show();let done=batch.records.filter(r=>r.state!=='PENDING').length;$('progressText').textContent=`Image ${Math.min(index+1,batch.records.length)} of ${batch.records.length} · ${done} completed · ${batch.summary.reviewed} reviewed`;$('bar').style.width=`${100*done/Math.max(1,batch.records.length)}%`;let s=batch.summary;$('summary').innerHTML=['uploaded_images','detection_completed','no_plate_detected','recognition_completed','inference_failures','reviewed','unreviewed'].map(k=>`<div class=metric><b>${s[k]}</b>${k.replaceAll('_',' ')}</div>`).join('');let r=record();if(!r)return;let z=r.result||{},rec=z.recognition||{},review=r.review||z.manual_review||{},resolved=resolution(z,review),root=`/api/artifact/${batch.batch_id}/${r.request_id}/`;$('raw').src=root+'raw';$('annotated').src=z.annotated_image?root+'annotated.jpg':'';$('detectedCrop').src=z.crop_reference?root+'crop.jpg':'';$('crop').src=z.recognition_crop_reference?root+z.recognition_crop_reference.artifact:(z.crop_reference?root+'crop.jpg':'');$('modelPrediction').textContent=rec.raw_text??'—';$('confidence').textContent=`Confidence: ${rec.raw_confidence?.toFixed(4)??'—'} · INFORMATIONAL ONLY`;$('structural').textContent=`Turkish structural validation: ${rec.structural_validation?.valid===true?'VALID':rec.structural_validation?.valid===false?'INVALID':'NOT AVAILABLE'}`;$('resolvedText').textContent=resolved.text??'—';$('statusBadge').textContent=resolved.status;$('statusBadge').className=`badge ${resolved.status==='OWNER CONFIRMED'?'confirmed':resolved.status==='OWNER CORRECTED'?'corrected':resolved.status.includes('FAILURE')?'failure':''}`;$('resolutionSource').textContent=`Resolution source: ${resolved.source}`;$('errors').textContent=(z.errors||[]).join(' · ');choices($('detChoices'),'det',['UNREVIEWED','CORRECT','INCORRECT'],review.detection_assessment||'UNREVIEWED');choices($('recognitionChoices'),'recognition',['UNREVIEWED','CORRECT','INCORRECT','NOT_APPLICABLE'],review.official_raw_assessment||review.recognition_assessment||(rec.raw_text?'UNREVIEWED':'NOT_APPLICABLE'));$('reason').value=review.detection_error_reason||'';$('corrected').value=review.corrected_plate_text||'';$('comment').value=review.owner_comment||'';renderTable()}
async function save(advance=false){let d=selected('det'),r=selected('recognition'),corrected=$('corrected').value.trim();if(advance&&(d==='UNREVIEWED'||r==='UNREVIEWED')){alert('Detection and Recognition require explicit owner decisions.');return}if(r==='INCORRECT'&&!corrected){alert('Corrected plate text is required when the project model prediction is incorrect.');return}if(r!=='INCORRECT'&&corrected){alert('Use INCORRECT when supplying corrected plate text.');return}let payload={request_id:record().request_id,detection_assessment:d,recognition_assessment:r,official_raw_assessment:r,detection_error_reason:$('reason').value,corrected_plate_text:corrected,owner_comment:$('comment').value};await api(`/api/batches/${batch.batch_id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});batch=await api(`/api/batches/${batch.batch_id}`);if(advance&&index<batch.records.length-1)index++;render()}
function renderTable(){$('rows').innerHTML=batch.records.map((r,i)=>{let z=r.result||{},q=z.recognition||{},v=r.review||{},resolved=resolution(z,v),root=`/api/artifact/${batch.batch_id}/${r.request_id}/`;return `<tr><td><img src="${root}raw"><br>${esc(r.safe_original_filename)}</td><td>${z.annotated_image?`<img src="${root}annotated.jpg">`:'—'}<br>${z.detection?.selected?.confidence?.toFixed(4)??'—'}</td><td><b>${esc(q.raw_text??'—')}</b><br>Confidence ${q.raw_confidence?.toFixed(4)??'—'} informational only</td><td><b>${esc(resolved.text??'—')}</b><br>${esc(resolved.source)}</td><td>Detection ${esc(v.detection_assessment||'UNREVIEWED')}<br>Recognition ${esc(v.official_raw_assessment||v.recognition_assessment||'UNREVIEWED')}</td><td>${esc(resolved.status)}<br><button data-open=${i}>Open</button></td></tr>`}).join('');$('rows').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{index=+b.dataset.open;$('guidedBtn').click();render()})}
$('start').onclick=start;$('resume').onchange=async()=>{if(!$('resume').value)return;batch=await api('/api/batches/'+$('resume').value);index=Math.max(0,batch.records.findIndex(r=>(r.review?.official_raw_assessment||r.review?.recognition_assessment)==='UNREVIEWED'));show();render()};$('previous').onclick=()=>{index=Math.max(0,index-1);render()};$('next').onclick=()=>{index=Math.min(batch.records.length-1,index+1);render()};$('save').onclick=()=>save(false);$('saveContinue').onclick=()=>save(true);$('guidedBtn').onclick=()=>{$('guided').classList.remove('hidden');$('tableView').classList.add('hidden')};$('tableBtn').onclick=()=>{$('guided').classList.add('hidden');$('tableView').classList.remove('hidden')};init().catch(e=>$('health').textContent='UNHEALTHY: '+e.message);
</script></body></html>"""
